import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group, Color } from 'three/webgpu';
import { texture, uniform, vec4 } from 'three/tsl';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const group = new Group();
  group.name = 'features-card-1-label';
  group.position.set(-3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 1.6;
  const height = 1.0;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({ transparent: true });

  let map = null;
  try {
    map = ctx.textureLoader.load('/prism-mock/home/nodes/cta-hero-isolated.png');
    map.colorSpace = 'srgb';
    material.colorNode = texture(map);
  } catch (e) {
    material.colorNode = vec4(uniform(new Color('#16161d')), 1.0);
  }

  const plane = new Mesh(geometry, material);
  plane.name = 'features-card-1-plane';
  group.add(plane);

  let textNode = null;
  try {
    textNode = createText({
      text: 'Features 1',
      fontAtlas: ctx.fontAtlas,
      font: 'Lora',
      weight: 400,
      size: 0.34,
      color: '#e8ecf2',
      align: 'left',
    });
    textNode.name = 'features-card-1-headline';
    textNode.position.set(-width / 2 + 0.1, -height / 2 + 0.15, 0.01);
    group.add(textNode);
  } catch (e) {
    // font atlas unavailable — skip text
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    if (textNode && textNode.userData && typeof textNode.userData.cleanup === 'function') {
      textNode.userData.cleanup();
    }
  };

  return group;
}
